class NomSucursal extends BaseNomSucursal
{

    public function setUp()
    {
        $this->hasOne('NomBanco', array('local' => 'idbanco', 'foreign' => 'idbanco', 'onDelete' => 'CASCADE'));
        /*$this->hasMany('NomCuentaBancaria', array('local' => 'idsucursal', 'foreign' => 'idsucursal'));*/
        parent::setUp();
    }

    /**
     * Obtiene los datos de sucursal dado las condiciones
     *
     * @param array $cond  Arreglo de condiciones
     * @param int   $limit Límite superior
     * @param int   $start Comienzo inferior
     *
     * @return array
     */
    public function buscarSucursal($cond = array(), $limit = null, $start = null)
    {
        try {
            $filter = " 0 = 0 ";
            if ($cond['idsucursal']) {
                $filter .= " and e.idsucursal = '" . $cond['idsucursal'] . "'";
            }
            if ($cond['idbanco']) {
                $filter .= " and e.idbanco = '" . $cond['idbanco'] . "'";
            }
            if ($cond['numero']) {
                $filter .= " and e.numero = '" . $cond['numero'] . "'";
            }
            if ($cond['direccion']) {
                $filter .= " and e.direccion = '" . $cond['direccion'] . "'";
            }
            if ($cond['sfFiltro'] != '') {
                $filter
                    .= " and (e.numero ilike '%" . $cond['sfFiltro'] . "%' OR e.direccion ilike '%"
                    . $cond['sfFiltro']
                    . "%')";
            }

            $q = new Doctrine_Query();
            $q->from('NomSucursal e')->where($filter);

            if (!is_null($limit) && !is_null($start)) {
                $q->limit($limit)->offset($start);
            }
            $resultado = $q->execute()->toArray();
            if ($cond['sfFiltro'] != '') {
                include_once Zend_Registry::get('config')->dir_aplication .
                    'configuracion/comun/models/bussines/UtilesDatosMaestros.php';
                $resultado = UtilesDatosMaestros::colorSearch(
                    $resultado,
                    array('numero', 'direccion'), array($cond['sfFiltro'], $cond['sfFiltro'])
                );
            }
            $cantidad = self::Cantidad($filter);
            return array('cant' => $cantidad, 'datos' => $resultado);
        } catch (Doctrine_Exception $ee) {
            return false;
        }
    }

    /**
     * Obtine todas las sucursales pertenecientes a un banco
     *
     * @param int $idbanco
     *
     * @author Ing. Lisvany Alonso Martinez
     *
     * @return bool
     */
    public function todasSucursales($idbanco)
    {
        try {
            $filter = " e.idbanco = '" . $idbanco . "'";

            $q = new Doctrine_Query();
            $sucursales = $q->from('NomSucursal e')->where($filter)->execute();

            $arraysucursales = $sucursales->toArray();

            return $arraysucursales;
        } catch (Doctrine_Exception $ee) {
            return false;
        }
    }

    /**
     * Obtiene las sucursales por ID de banco
     *
     * @param int $idbanco Identificador de banco
     *
     * @return array
     */
    public function buscarSucursalesByIdBanco($idbanco)
    {
        $q = new Doctrine_Query();
        $cons = $q->select('*')->from('NomSucursal e')->where("e.idbanco = $idbanco")->execute();
        return $cons;
    }

    /**
     * Obtiene la cantidad de elementos que posee sucursal dado un filtro de condiciones
     *
     * @param string $filter Filtro de condiciones
     *
     * @return int
     */
    public function Cantidad($filter)
    {
        $q = new Doctrine_Query();
        if ($filter) {
            $count = $q->select("COUNT(e.idsucursal) cant ")->from("NomSucursal e")->where($filter)->execute();
        } else {
            $count = $q->select("COUNT(e.idsucursal) cant ")->from("NomSucursal e")->execute();
        }

        $cant = $count->toArray();
        return $cant[0]['cant'];
    }

}
